pub type Account = { username: Str; password_hash: Str; }

fn create_account(username: Str, password: Str) -> Result[Account, Str] {
  if username.len() < 3 { return Err("username too short (min 3 chars)"); }
  if username.len() > 20 { return Err("username too long (max 20 chars)"); }
  if password.len() < 8 { return Err("password too short (min 8 chars)"); }
  if password.len() > 128 { return Err("password too long (max 128 chars)"); }
  if username == password { return Err("password must not match username"); }

  let account = Account{ username: username, password_hash: "hashed_" + password };
  return Ok(account);
}

fn main() -> Int {
  match create_account("alice", "secure123") {
    Ok(_) => return 1,
    Err(_) => return 0,
  }
}
